// Respiratory Therapy Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: gas laws, ABG interpretation and therapy choices.
import {q, mix} from './q.js';
const EGAN='Egan’s Fundamentals of Respiratory Care', DHO='Simmers, DHO: Health Science', AARC='American Association for Respiratory Care';
const FOUND='Foundations of Respiratory Care', AP='Applied anatomy & Physiology', ASSESS='Assessment of Respiratory Disorder', DIS='Cardiopulmonary Diseases', THER='Basic Therapeutics', EDU='Patient Education and Long-Term Care';

export default {
 id:'respiratory-therapy-1',
 event:'Respiratory Therapy',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Egan’s Fundamentals of Respiratory Care, DHO: Health Science and the AARC',
 plan:[{area:FOUND,weight:20},{area:AP,weight:10},{area:ASSESS,weight:20},{area:DIS,weight:20},{area:THER,weight:20},{area:EDU,weight:10}],
 questions:mix([
  q(FOUND,'Which organization awards the CRT and RRT credentials?','The NBRC',['The AARC','The FDA','The CDC'],'B','The National Board for Respiratory Care (NBRC) gives the credentialing exams. The AARC is the professional association for respiratory therapists.',EGAN),
  q(FOUND,'As the diaphragm contracts and chest volume increases, pressure in the lungs falls and air flows in. Which gas law describes this?','Boyle’s law',['Charles’ law','Dalton’s law','Henry’s law'],'D','Boyle’s law states that at constant temperature, pressure and volume are inversely related (P1V1 = P2V2). Larger volume means lower pressure.',EGAN),
  q(FOUND,'At sea level (760 mm Hg), what is the approximate partial pressure of oxygen in dry room air?','About 160 mm Hg',['About 21 mm Hg','About 100 mm Hg','About 760 mm Hg'],'A','By Dalton’s law, PO₂ = 0.21 × 760 ≈ 160 mm Hg. Alveolar PO₂ is lower, about 100 mm Hg, because of water vapor and carbon dioxide.',EGAN),
  q(FOUND,'In the United States, what color is a medical oxygen cylinder?','Green',['Blue','Yellow','Gray'],'C','U.S. medical oxygen cylinders are green. Internationally, oxygen is often white, so labels must always be checked.',EGAN),
  q(FOUND,'Why is oxygen a fire hazard even though it does not burn itself?','It supports and speeds up combustion',['It is highly explosive under pressure','It turns into a flammable gas when warmed','It ignites when it touches skin'],'B','Oxygen-enriched air makes materials ignite more easily and burn faster and hotter, so smoking and open flames are prohibited near oxygen.',EGAN),
  q(FOUND,'What is the purpose of the Pin Index Safety System on small gas cylinders?','To prevent connecting the wrong gas',['To measure how much gas is left','To lower the cylinder pressure','To humidify the gas inside the tank'],'D','Each gas has a unique pin position on the yoke, so a regulator for one gas cannot fit a cylinder of another. DISS does the same for low-pressure connections.',EGAN),
  q(FOUND,'Which measure helps prevent ventilator-associated pneumonia?','Raising the head of the bed',['Keeping the patient flat','Changing the circuit every hour','Avoiding oral care'],'A','Raising the head of the bed reduces aspiration of stomach contents. Oral care, minimizing sedation and hand hygiene are also part of VAP prevention bundles.',EGAN),
  q(FOUND,'Why are medical gases humidified for patients with an artificial airway?','Dry gas dries the airway and thickens secretions',['Humidity raises the oxygen concentration','Water vapor kills bacteria in the tubing','Humidity lowers airway pressure'],'C','An artificial airway bypasses the nose, which normally warms and humidifies air. Dry gas can damage the airway lining and cause thick, hard-to-clear secretions.',EGAN),
  q(FOUND,'A blood gas analyzer gives nearly identical results when one sample is tested five times, but all are far from the true value. Its results are:','Precise but not accurate',['Accurate but not precise','Both accurate and precise','Neither precise nor consistent'],'B','Precision is reproducibility; accuracy is closeness to the true value. Consistent results that are all wrong suggest a calibration error.',EGAN),
  q(FOUND,'A competent patient declines intubation, and the team honors the decision. Which ethical principle is being respected?','Autonomy',['Beneficence','Justice','Veracity'],'D','Autonomy is the patient’s right to make informed decisions about their own care, including refusing treatment.',EGAN),
  q(AP,'Which nerve controls the diaphragm?','The phrenic nerve',['The vagus nerve','The intercostal nerve','The recurrent laryngeal nerve'],'A','The phrenic nerve arises from C3–C5 (“C3, 4, 5 keeps the diaphragm alive”). High cervical spinal injuries can stop breathing.',EGAN),
  q(AP,'What is the main role of pulmonary surfactant?','To lower alveolar surface tension',['To trap inhaled dust and bacteria','To carry oxygen in the blood','To produce mucus in the bronchi'],'C','Surfactant, made by type II alveolar cells, reduces surface tension so alveoli do not collapse at the end of exhalation.',EGAN),
  q(AP,'Which stimulus most strongly drives breathing in a healthy person?','A rise in arterial carbon dioxide',['A fall in arterial oxygen','A rise in blood glucose','A fall in body temperature'],'B','Central chemoreceptors respond to changes in CO₂ and pH in the cerebrospinal fluid. The hypoxic drive becomes more important in some chronic CO₂ retainers.',EGAN),
  q(AP,'What is a typical tidal volume for a healthy adult at rest?','About 500 mL',['About 50 mL','About 1,500 mL','About 5,000 mL'],'D','Normal tidal volume is about 5–7 mL/kg of ideal body weight, roughly 500 mL. About 5,000 mL is closer to total lung capacity.',EGAN),
  q(AP,'Fever and acidosis shift the oxyhemoglobin dissociation curve to the right. What does this mean?','Hemoglobin releases oxygen to tissues more easily',['Hemoglobin holds on to oxygen more tightly','The blood carries no oxygen','Carbon dioxide cannot leave the blood'],'A','A right shift lowers hemoglobin’s affinity for oxygen, so more oxygen is unloaded in active, warm, acidic tissues.',EGAN),
  q(ASSESS,'An ABG shows pH 7.30, PaCO₂ 55 mm Hg and HCO₃⁻ 24 mEq/L. What is the interpretation?','Acute respiratory acidosis',['Metabolic acidosis','Respiratory alkalosis','Compensated metabolic alkalosis'],'C','The pH is low (acidosis), PaCO₂ is high (respiratory cause) and HCO₃⁻ is normal (no compensation yet), so this is acute respiratory acidosis from hypoventilation.',EGAN),
  q(ASSESS,'An anxious patient’s ABG shows pH 7.50, PaCO₂ 30 mm Hg and HCO₃⁻ 23 mEq/L. What is the interpretation?','Respiratory alkalosis',['Respiratory acidosis','Metabolic alkalosis','Metabolic acidosis'],'B','A high pH with low PaCO₂ means the patient is blowing off too much CO₂ (hyperventilation), causing respiratory alkalosis.',EGAN),
  q(ASSESS,'A high-pitched, musical sound heard mainly during exhalation suggests:','Narrowed airways',['Fluid in the alveoli','Upper airway obstruction','Pleural inflammation'],'D','Wheezes come from air moving through narrowed airways, as in asthma. Crackles suggest fluid or opening of collapsed alveoli, stridor suggests upper airway obstruction, and a friction rub suggests pleural inflammation.',EGAN),
  q(ASSESS,'A child has a loud, high-pitched sound on inspiration that can be heard without a stethoscope. What is this?','Stridor',['Wheezing','Crackles','Rhonchi'],'A','Inspiratory stridor signals upper airway narrowing, as in croup or epiglottitis, and can be an emergency.',EGAN),
  q(ASSESS,'Digital clubbing is most often associated with which condition?','Chronic low blood oxygen',['Acute asthma attack','Recent ankle sprain','Seasonal allergies'],'C','Clubbing, a rounded enlargement of the fingertips, develops over time with chronic hypoxemia, as in cystic fibrosis, lung cancer and some heart diseases.',EGAN),
  q(ASSESS,'Which spirometry finding indicates an obstructive lung disease?','An FEV1/FVC ratio below 70%',['A normal FEV1/FVC with low total lung capacity','A high FEV1 with a normal FVC','An FEV1/FVC ratio of 85%'],'B','Obstruction slows airflow out of the lungs, lowering FEV1 more than FVC. A low total lung capacity with a normal ratio suggests restriction.',EGAN),
  q(ASSESS,'Which pulmonary function finding is characteristic of restrictive lung disease?','A reduced total lung capacity',['An increased residual volume','An FEV1/FVC below 50%','A high peak flow'],'D','Restrictive diseases such as pulmonary fibrosis limit lung expansion, reducing total lung capacity and other volumes.',EGAN),
  q(ASSESS,'Which chest X-ray finding is typical of advanced emphysema?','Flattened diaphragms and hyperinflated lungs',['Whited-out lung fields on both sides','A large heart shadow only','Fluid filling the lower lobes'],'A','Air trapping causes hyperinflation, flattened diaphragms, more space between ribs and a long, narrow heart shadow.',EGAN),
  q(ASSESS,'During a severe asthma attack, the patient’s abdomen moves inward on inspiration. What does this suggest?','Respiratory muscle fatigue',['Normal diaphragm function','Improvement in airflow','Recovery from the attack'],'C','Paradoxical abdominal movement suggests the diaphragm is fatiguing. The patient may soon need ventilatory support.',EGAN),
  q(ASSESS,'In an asthma action plan, a peak flow below 50% of the patient’s personal best is in which zone?','Red zone',['Green zone','Yellow zone','Blue zone'],'B','Green is 80–100% of personal best, yellow 50–80% (caution), and red below 50% (medical alert; use rescue medication and seek help).',AARC),
  q(DIS,'A patient with asthma does not respond to repeated bronchodilator treatments. What is this called?','Status asthmaticus',['Exercise-induced bronchospasm','Chronic bronchitis','Allergic rhinitis'],'D','Status asthmaticus is a severe attack that does not respond to standard treatment and can lead to respiratory failure.',EGAN),
  q(DIS,'How is chronic bronchitis defined clinically?','A productive cough 3 months a year for 2 years',['Destroyed alveolar walls on a CT scan','Reversible wheezing after allergen exposure','A single episode of cough after a cold'],'A','Chronic bronchitis is defined by its symptoms. Emphysema is defined by structural destruction of the alveoli.',EGAN),
  q(DIS,'Which assessment finding is typical over an area of lobar pneumonia with consolidation?','Bronchial breath sounds and dullness to percussion',['Absent breath sounds and hyperresonance','Normal vesicular breath sounds','A pleural friction rub only'],'C','Consolidated lung transmits sound well, so bronchial breath sounds are heard, and dense tissue is dull to percussion. Hyperresonance suggests pneumothorax.',EGAN),
  q(DIS,'What is the hallmark of acute respiratory distress syndrome (ARDS)?','Hypoxemia that does not improve with high oxygen',['Rapid improvement with a bronchodilator','Fluid in the lungs from left heart failure','Wheezing triggered by allergens'],'B','ARDS is a noncardiogenic pulmonary edema with leaky capillaries and collapsed alveoli, causing refractory hypoxemia. PEEP is a key part of treatment.',EGAN),
  q(DIS,'A postoperative patient suddenly develops sharp chest pain, dyspnea and tachycardia. Which condition should be suspected?','Pulmonary embolism',['Asthma','Chronic bronchitis','Sleep apnea'],'D','A clot from the legs can lodge in the pulmonary arteries, causing ventilation without perfusion (V/Q mismatch). Immobility after surgery raises the risk.',EGAN),
  q(DIS,'Which therapy is a daily priority for patients with cystic fibrosis?','Airway clearance therapy',['Bed rest','Fluid restriction','A low-calorie diet'],'A','Thick mucus blocks airways and promotes infection. Daily airway clearance (chest physiotherapy, devices) plus inhaled medications helps keep the airways open.',EGAN),
  q(DIS,'A tall, thin young man has sudden chest pain and absent breath sounds on one side, with hyperresonance. What is likely?','Pneumothorax',['Pleural effusion','Pneumonia','Atelectasis'],'C','Air in the pleural space collapses the lung, so breath sounds are absent and percussion is hyperresonant. Effusion and pneumonia are dull to percussion.',EGAN),
  q(DIS,'What is the most common treatment for moderate to severe obstructive sleep apnea?','CPAP during sleep',['Supplemental oxygen only','Daily bronchodilators','Antibiotics'],'B','Continuous positive airway pressure splints the upper airway open during sleep, preventing collapse and apneas.',EGAN),
  q(DIS,'Respiratory distress syndrome in premature newborns is caused mainly by:','A lack of surfactant',['A bacterial infection','Swallowed meconium','A heart defect'],'D','Surfactant production matures late in pregnancy, so premature infants’ alveoli collapse. Treatment includes surfactant replacement and CPAP.',EGAN),
  q(DIS,'Idiopathic pulmonary fibrosis is classified as which type of lung disease?','Restrictive',['Obstructive','Reversible','Infectious'],'A','Scarring stiffens the lungs and reduces lung volumes, a restrictive pattern. Patients often have fine crackles and clubbing.',EGAN),
  q(THER,'A patient on a nasal cannula at 3 L/min receives approximately what FiO₂?','32%',['24%','44%','60%'],'C','A rough rule is 21% plus about 4% per L/min: 21 + (3 × 4) ≈ 33%, so about 32%. The actual FiO₂ varies with the patient’s breathing pattern.',EGAN),
  q(THER,'Which device delivers a precise, fixed oxygen concentration?','Venturi mask',['Nasal cannula','Simple mask','Nonrebreather mask'],'B','A Venturi mask entrains a set amount of room air, giving a precise FiO₂ regardless of breathing pattern. It is useful for patients with COPD.',EGAN),
  q(THER,'How does a high-flow nasal cannula differ from a standard nasal cannula?','It gives heated, humidified high flows',['It delivers only room air','It is used only while the patient sleeps','It replaces the need for an airway'],'D','High-flow systems deliver heated, humidified gas at flows up to about 60 L/min, providing a more reliable FiO₂ and some positive pressure.',EGAN),
  q(THER,'How does ipratropium bromide relieve bronchospasm?','It blocks acetylcholine at airway receptors',['It stimulates beta-2 receptors','It reduces inflammation as a steroid','It thins mucus'],'A','Ipratropium is an anticholinergic bronchodilator. Albuterol stimulates beta-2 receptors, and corticosteroids reduce inflammation.',EGAN),
  q(THER,'What is the main goal of incentive spirometry after surgery?','To prevent atelectasis',['To measure blood oxygen','To deliver medication','To strengthen the abdominal muscles'],'C','Sustained maximal inspirations re-expand alveoli and help prevent postoperative atelectasis and pneumonia.',EGAN),
  q(THER,'What is the purpose of postural drainage with chest percussion?','To move secretions to large airways',['To raise blood pressure','To deliver oxygen to the alveoli','To reduce airway inflammation'],'B','Positioning uses gravity to drain specific lung segments, and percussion loosens secretions so they can be coughed out or suctioned.',EGAN),
  q(THER,'How does PEEP improve oxygenation in a ventilated patient?','It keeps alveoli open at end-exhalation',['It increases the breathing rate','It removes carbon dioxide directly','It lowers the oxygen concentration'],'D','Positive end-expiratory pressure prevents alveolar collapse, increases the area for gas exchange and improves oxygenation.',EGAN),
  q(THER,'What is the maximum duration of each suction pass in an adult?','10–15 seconds',['30 seconds','1 minute','2 minutes'],'A','Suctioning removes oxygen with secretions. Short passes with oxygen given before and after reduce hypoxemia and bradycardia.',EGAN),
  q(THER,'To reduce the risk of oxygen toxicity, the FiO₂ should be kept below what level when possible?','0.60 (60%)',['0.21 (21%)','0.30 (30%)','1.00 (100%)'],'C','Prolonged exposure to high oxygen concentrations can damage the lungs. Clinicians use the lowest FiO₂ that keeps oxygen levels acceptable.',EGAN),
  q(THER,'What SpO₂ target is commonly used for patients with COPD who retain carbon dioxide?','88–92%',['80–84%','95–100%','98–100%'],'B','Lower targets avoid worsening CO₂ retention while keeping tissues oxygenated.',EGAN),
  q(EDU,'Why is pursed-lip breathing taught to patients with COPD?','It keeps small airways open longer',['It increases the breathing rate','It strengthens the vocal cords','It replaces the need for inhalers'],'D','Exhaling through pursed lips creates back pressure that prevents early airway collapse, reducing air trapping and breathlessness.',AARC),
  q(EDU,'When using a metered-dose inhaler without a spacer, what should the patient do after inhaling the puff?','Hold the breath about 10 seconds',['Exhale immediately','Cough forcefully','Take several rapid breaths'],'A','Breath-holding gives the medication time to settle in the airways. The inhale should be slow and deep.',AARC),
  q(EDU,'Which intervention does the most to slow the progression of COPD?','Quitting smoking',['Daily antibiotics','Bed rest','Avoiding all exercise'],'C','Smoking cessation is the only intervention shown to slow the decline in lung function in smokers with COPD.',AARC),
  q(EDU,'What does a pulmonary rehabilitation program usually include?','Exercise training and education',['Surgery and general anesthesia','Antibiotics only','Complete bed rest for weeks'],'B','Pulmonary rehab improves exercise tolerance, symptoms and quality of life through supervised exercise, education and support.',AARC),
  q(EDU,'Long-term home oxygen therapy is generally indicated when resting SpO₂ is at or below:','88%',['95%','92%','98%'],'D','Criteria typically include a resting PaO₂ of 55 mm Hg or less or an SpO₂ of 88% or less. Long-term oxygen improves survival in these patients.',AARC)
 ],89)
};
